    def close(self) -> None:
        """Close API"""
        if self._kafka_client:
            self._kafka_client.close()

    def _create_kafka_message(
        self,
        msg_type: str,
        payload: dict,
        bts_id: str,
        run_id: Optional[Union[str, UUID]] = None,
        case_id: Optional[Union[str, UUID]] = None,
        step_id: Optional[str] = None,
        msg_version: str = "1.0",
    ) -> dict:
        """
        Create Kafka message.

        :param msg_type: Message type
        :param payload: Message payload
        :param bts_id: BTS ID
        :param run_id: Test run ID
        :param case_id: Test case ID
        :param step_id: Test step ID
        :param msg_version: Message version. Default "1.0".
        :return: Kafka message
        """
        msg: dict[str, Any] = {
            "header": {
                "msg_type": msg_type,
                "msg_version": msg_version,
                "msg_id": uuid4(),
                "msg_send_time": datetime.now(tz=timezone.utc),
                "producer": "marvin_client",
                "host_computer_name": self._settings.client_host_name,
                "host_ip": self._settings.client_host_ip_address,
            },
            "meta": {"sut_id": bts_id},
            "payload": payload,
        }

        # Test phase meta parameters
        if run_id:
            meta = msg["meta"]
            meta["test_level"] = "test_run"
            meta["run_id"] = run_id
            if case_id:
                meta["test_level"] = "test_case"
                meta["case_id"] = case_id
                if step_id:
                    meta["test_level"] = "test_step"
                    meta["step_id"] = step_id

        return msg

    def _check_test_run_exists_in_summary_view(self, run_id: str) -> None:
        """
        Check that test run exists in Summary view.
        Summary view API is polled up to 120 seconds to wait that test run is created, i.e. the test run creation
        Kafka message has been processed successfully.

        :param run_id: Test run ID
        :raises MarvinClientException: If test run does not exist in Summary view or the check failed for any reason
        """
        self._send_summary_view_api_get_request(
            f"/api/v1/test_runs/{run_id}/exists", TEST_RUN_CREATION_TIMEOUT_IN_SUMMARY_VIEW
        )

    def _check_test_case_exists_in_summary_view(self, run_id: str, case_id: str) -> None:
        """
        Check that test case exists in Summary view.
        Summary view API is polled up to 120 seconds to wait that test case is created, i.e. the test case creation
        Kafka message has been processed successfully.

        :param run_id: Test run ID
        :param case_id: Test case ID
        :raises MarvinClientException: If test case does not exist in Summary view or the check failed for any reason
        """
        self._send_summary_view_api_get_request(
            f"/api/v1/test_runs/{run_id}/test_cases/{case_id}/exists", TEST_CASE_CREATION_TIMEOUT_IN_SUMMARY_VIEW
        )

    def _send_summary_view_api_get_request(self, endpoint: str, timeout: int) -> Any:
        """
        Execute Summary view API HTTP GET command.

        :param endpoint: URL endpoint without host part, e.g. "/api/v1/test_runs/{run_id}/exists"
        :param timeout: Operation timeout in seconds
        :raises MarvinClientException: If operation fails
        """
        expiration_time = time.monotonic() + timeout

        error_msg = None

        while time.monotonic() < expiration_time:
            try:
                response = requests.get(
                    f"{self._settings.summary_view_api}{endpoint}",
                    timeout=timeout,
                    proxies=NO_PROXY,
                )
                payload = response.json()

                if payload["result"] == "ok":
                    return payload

                error_msg = payload["result_info"]["text"]

            except Exception as ex:
                error_msg = str(ex)

            time.sleep(SUMMARY_VIEW_API_RETRY_DELAY)

        raise MarvinClientException(error_msg)

    def _check_test_case_exists_in_meta_service(self, case_id: str) -> None:
        """
        Check that test case exists in Meta service.
        Meta service API is polled up to 120 seconds to wait that test case is created, i.e. the test case creation
        Kafka message has been processed successfully.

        :param case_id: Test case ID
        :raises MarvinClientException: If test case does not exist in Meta service or the check failed for any reason
        """
        self._send_meta_service_api_get_request(
            f"/api/v1/test_cases/{case_id}/exists", TEST_CASE_CREATION_TIMEOUT_IN_META_SERVICE
        )

    def _send_meta_service_api_get_request(self, endpoint: str, timeout: int) -> Any:
        """
        Execute Meta service API HTTP GET command.

        :param endpoint: URL endpoint without host part, e.g. "/api/v1/test_cases/{case_id}/exists"
        :param timeout: Operation timeout in seconds
        :raises MarvinClientException: If operation fails
        """
        expiration_time = time.monotonic() + timeout

        error_msg = None

        while time.monotonic() < expiration_time:
            try:
                response = requests.get(
                    f"{self._settings.meta_service_api}{endpoint}",
                    timeout=timeout,
                    proxies=NO_PROXY,
                )
                response.raise_for_status()

                if response.content:
                    return response.json()
                else:
                    return None

            except Exception as ex:
                error_msg = str(ex)

            time.sleep(META_SERVICE_API_RETRY_DELAY)

        raise MarvinClientException(error_msg)
